body.script:
                    async function loadExternalHTML(url, containerId) {
                        try {
                            // Fetch the external file
                            const response = await fetch(url);

                            // Check if the file exists and was fetched successfully
                            if (!response.ok) {
                                throw new Error(`Could not fetch ${url}. Status: ${response.status}`);
                            }

                            // Convert the response to text HTML
                            const htmlText = await response.text();

                            // Insert it into your container
                            document.getElementById(containerId).innerHTML = htmlText;
                        } catch (error) {
                            console.error("Error loading the HTML:", error);
                            document.getElementById(containerId).innerHTML = "
Failed to load content.";
                        }
                    }
                    loadExternalHTML("./index.html", "content-container");
